169	    // Directly extend AtomicReference for intrinsics and also to keep memory overhead low.
170	    private final class Entries extends AtomicReference<List<E>> implements Runnable {
171	
172	        private final String hostname;
173	        // Needs to be package-private to be able to access it via the AtomicReferenceFieldUpdater
174	        volatile ScheduledFuture<?> expirationFuture;
175	
176	        Entries(String hostname) {
177	            super(Collections.<E>emptyList());
178	            this.hostname = hostname;
179	        }
180	
181	        boolean add(E e, int ttl, EventLoop loop) {
182	            // Fast-path: avoid mutating a dead Entries. scheduleCacheExpirationIfNeeded will
183	            // detect CANCELLED definitively, but checking early avoids unnecessary list writes
184	            // that could briefly re-expose evicted data to concurrent get() callers.
185	            if (FUTURE_UPDATER.get(this) == CANCELLED) {
186	                return false;
187	            }
188	            if (!shouldReplaceAll(e)) {
189	                for (;;) {
190	                    List<E> entries = get();
191	                    if (!entries.isEmpty()) {
192	                        final E firstEntry = entries.get(0);
193	                        if (shouldReplaceAll(firstEntry)) {
194	                            assert entries.size() == 1;
195	
196	                            if (compareAndSet(entries, singletonList(e))) {
197	                                return scheduleCacheExpirationIfNeeded(ttl, loop);
198	                            } else {
199	                                // Need to try again as CAS failed
200	                                continue;
201	                            }
202	                        }
203	
204	                        // Create a new List for COW semantics
205	                        List<E> newEntries = new ArrayList<E>(entries.size() + 1);
206	                        int i = 0;
207	                        E replacedEntry = null;
208	                        do {
209	                            E entry = entries.get(i);
210	                            // Only add old entry if the address is not the same as the one we try to add as well.
211	                            // In this case we will skip it and just add the new entry as this may have
212	                            // more up-to-date data and cancel the old after we were able to update the cache.
213	                            if (!Cache.this.equals(e, entry)) {
214	                                newEntries.add(entry);
215	                            } else {
216	                                replacedEntry = entry;
217	                                newEntries.add(e);
218	
219	                                ++i;
220	                                for (; i < entries.size(); ++i) {
221	                                    newEntries.add(entries.get(i));
222	                                }
223	                                break;
224	                            }
225	                        } while (++i < entries.size());
226	                        if (replacedEntry == null) {
227	                            newEntries.add(e);
228	                        }
229	                        sortEntries(hostname, newEntries);
230	
231	                        if (compareAndSet(entries, Collections.unmodifiableList(newEntries))) {
232	                            return scheduleCacheExpirationIfNeeded(ttl, loop);
233	                        }
234	                    } else if (compareAndSet(entries, singletonList(e))) {
235	                        return scheduleCacheExpirationIfNeeded(ttl, loop);
236	                    }
237	                }
238	            } else {
239	                set(singletonList(e));
240	                return scheduleCacheExpirationIfNeeded(ttl, loop);
241	            }
242	        }
