244	        private boolean scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
245	            for (;;) {
246	                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
247	                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
248	                // we can reconsider.
249	                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
250	                if (oldFuture == CANCELLED) {
251	                    // This Entries was already evicted from resolveCache by a concurrent expiration.
252	                    // Signal the caller (cache()) to retry with a fresh Entries.
253	                    return false;
254	                }
255	                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
256	                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
257	                    // It is possible that
258	                    // 1. task will fire in between this line, or
259	                    // 2. multiple timers may be set if there is concurrency
260	                    // (1) If the task fires and sets CANCELLED before our CAS, the next loop iteration returns false.
261	                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
262	                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
263	                        if (oldFuture != null) {
264	                            oldFuture.cancel(true);
265	                        }
266	                        return true;
267	                    } else {
268	                        // There was something else scheduled in the meantime... Cancel and try again.
269	                        newFuture.cancel(true);
270	                    }
271	                } else {
272	                    return true;
273	                }
274	            }
275	        }
276	
277	        boolean clearAndCancel() {
278	            // Set CANCELLED before clearing data so any concurrent scheduleCacheExpirationIfNeeded
279	            // call sees CANCELLED and returns false. If data were cleared first, a concurrent caller
280	            // could win the future CAS (CANCELLED not yet set), return true to cache(), and then
281	            // have its data immediately wiped when CANCELLED is set on the next step.
282	            ScheduledFuture<?> expirationFuture = FUTURE_UPDATER.getAndSet(this, CANCELLED);
283	            List<E> entries = getAndSet(Collections.<E>emptyList());
284	            if (expirationFuture != null && expirationFuture != CANCELLED) {
285	                expirationFuture.cancel(false);
286	            }
287	            return !entries.isEmpty();
288	        }
