290	        @Override
291	        public void run() {
292	            // We always remove all entries for a hostname once one entry expire. This is not the
293	            // most efficient to do but this way we can guarantee that if a DnsResolver
294	            // be configured to prefer one ip family over the other we will not return unexpected
295	            // results to the enduser if one of the A or AAAA records has different TTL settings.
296	            //
297	            // As a TTL is just a hint of the maximum time a cache is allowed to cache stuff it's
298	            // completely fine to remove the entry even if the TTL is not reached yet.
299	            //
300	            // See https://github.com/netty/netty/issues/7329
301	            // Set CANCELLED before removing from the map so any concurrent scheduleCacheExpirationIfNeeded
302	            // call always sees CANCELLED and returns false (triggering a retry in cache()) rather than
303	            // succeeding its future CAS, returning true, and having the data wiped immediately after.
304	            clearAndCancel();
305	
306	            resolveCache.remove(hostname, this);
307	        }
308	    }
